WITH sessions_by_customer AS (SELECT customer_id, MAX(started_at) AS latest_started_at, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM sessions GROUP BY customer_id) SELECT customers.id, customers.city, customers.segment, sessions_by_customer.latest_started_at, sessions_by_customer.country_list FROM customers INNER JOIN sessions_by_customer ON customers.id = sessions_by_customer.customer_id;
